/** Deliverable 2 is the Architect's own parts, assembled; the editor writes the rest. */
export function composeArchitect(agents: { id: ArchId; text: string }[]): string {
  const t = (id: ArchId) => agents.find((a) => a.id === id)?.text.trim() ?? ""; const body = (["AR1", "AR2", "AR3", "AR4", "AR5"] as ArchId[]).map((id) => t(id).replace(/^# /gm, "## ")).filter(Boolean).join("\n\n");
  const ed = t("EDIT"); const find = (h: string) => { const m = new RegExp(`^# ${h}[^\\n]*\\n[\\s\\S]*?(?=^# Deliverable|$(?![\\s\\S]))`, "m").exec(ed); return m?.[0].trim() ?? ""; };
  const d = (n: number) => find(`Deliverable ${n}:`); const miss = (n: number) => `# Deliverable ${n}\n\n> Not written: the editor did not finish (a cost ceiling or an error stopped the run).\n`;
  return [d(1) || miss(1), `# Deliverable 2: Comprehensive Country Statecraft Strategy\n\n${body || "> No agent finished."}`, d(3) || miss(3), d(4) || miss(4), d(5) || miss(5), d(6) || miss(6), reviewTail(agents)].filter(Boolean).join("\n\n");
}
export const deliverableOf = (report: string, n: number) => { const m = new RegExp(`^# Deliverable ${n}:[^\\n]*\\n([\\s\\S]*?)(?=^# Deliverable|$(?![\\s\\S]))`, "m").exec(report); return m?.[1].trim() ?? ""; };

// ---- the decision dashboard: structured output, validated ----
export type Initiative = { id: string; name: string; horizon: "short" | "medium" | "long"; pillar: Pillar6; lead: string; partners: string[]; funding: string; status: string; outcome: string; kpi: string; risk: string; gate: string; gateDate: string | null; dependencies: string[]; startMonth: number; endMonth: number };
export type Dashboard = { initiatives: Initiative[]; indicators: { name: string; signal: string; threshold: string; owner: string }[]; gates: { name: string; when: string; decision: string }[]; risks: { name: string; likelihood: string; impact: "low" | "medium" | "high"; mitigation: string }[] };
const s = (v: unknown, n = 200) => (typeof v === "string" ? v.replace(/[<>\u0000-\u001F]/g, " ").trim().slice(0, n) : ""); const arr = (v: unknown, n: number) => (Array.isArray(v) ? v.slice(0, n) : []);
