export function parseDashboard(report: string): Dashboard | null {
  const m = /<dashboard>([\s\S]*?)<\/dashboard>/.exec(report); if (!m) return null; let j: Record<string, unknown>; try { j = JSON.parse(m[1].trim().replace(/^```json|```$/g, "")) as Record<string, unknown>; } catch { return null; }
  const ini = arr(j.initiatives, 40).map((x): Initiative | null => { const o = x as Record<string, unknown>; const id = s(o.id, 12); if (!id || !HZ.has(String(o.horizon)) || !PL.has(String(o.pillar))) return null; const a = Math.max(0, Math.min(240, Number(o.startMonth) || 0)); const b = Math.max(a + 1, Math.min(240, Number(o.endMonth) || a + 12));
    return { id, name: s(o.name, 120), horizon: o.horizon as Initiative["horizon"], pillar: o.pillar as Pillar6, lead: s(o.lead, 120), partners: arr(o.partners, 6).map((p) => s(p, 80)).filter(Boolean), funding: s(o.funding, 120) || "not estimated", status: s(o.status, 30) || "proposed", outcome: s(o.outcome, 200), kpi: s(o.kpi, 200), risk: s(o.risk, 200), gate: s(o.gate, 160), gateDate: /^\d{4}-\d{2}$/.test(String(o.gateDate)) ? String(o.gateDate) : null, dependencies: arr(o.dependencies, 8).map((d) => s(d, 12)).filter(Boolean), startMonth: a, endMonth: b }; }).filter((x): x is Initiative => !!x);
  if (!ini.length) return null;
  return { initiatives: ini, indicators: arr(j.indicators, 20).map((x) => { const o = x as Record<string, unknown>; return { name: s(o.name, 120), signal: s(o.signal, 200), threshold: s(o.threshold, 160), owner: s(o.owner, 100) }; }).filter((x) => x.name), gates: arr(j.gates, 20).map((x) => { const o = x as Record<string, unknown>; return { name: s(o.name, 120), when: s(o.when, 80), decision: s(o.decision, 200) }; }).filter((x) => x.name),
    risks: arr(j.risks, 20).map((x) => { const o = x as Record<string, unknown>; return { name: s(o.name, 140), likelihood: s(o.likelihood, 40), impact: (["low", "medium", "high"].includes(String(o.impact)) ? o.impact : "medium") as "low" | "medium" | "high", mitigation: s(o.mitigation, 200) }; }).filter((x) => x.name) };
}

// ---- intelligence-tradecraft checks (benchmarked to the published ICD 203 standards; not a claim about any agency's practice) ----
export type Check = { id: string; en: string; ar: string; pass: boolean; note: B };
export function tradecraftChecks(report: string): Check[] {
  const n = (re: RegExp) => (report.match(re) ?? []).length; const dash = parseDashboard(report); const c = (id: string, en: string, ar: string, pass: boolean, ne: string, na: string): Check => ({ id, en, ar, pass, note: { en: ne, ar: na } });
  return [
    c("sourcing", "Sourcing: claims cite fact ids and a source list", "المصادر: الادعاءات تحيل إلى معرّفات الحقائق وقائمة مصادر", n(/\[F\d+/g) >= 8 && /Sources/i.test(report), `${n(/\[F\d+/g)} fact citations`, `${n(/\[F\d+/g)} إحالة`),
    c("uncertainty", "Uncertainty: confidence stated on judgments", "عدم اليقين: الثقة معلنة على الأحكام", n(/\b(high|moderate|low) confidence|confidence: (high|moderate|low)/gi) >= 3, `${n(/\b(high|moderate|low) confidence|confidence: (high|moderate|low)/gi)} confidence statements`, `${n(/\b(high|moderate|low) confidence|confidence: (high|moderate|low)/gi)} عبارة ثقة`),
    c("assumptions", "Assumptions kept apart from judgments", "الافتراضات منفصلة عن الأحكام", /key assumptions/i.test(report) && n(/assum(e|es|ed|ption|ptions)\b/gi) >= 3, `${n(/assum(e|es|ed|ption|ptions)\b/gi)} mentions, key-assumptions list ${/key assumptions/i.test(report) ? "present" : "missing"}`, `${n(/assum(e|es|ed|ption|ptions)\b/gi)} إشارة`),
    c("alternatives", "Alternatives: Options A, B, C and four scenarios", "البدائل: الخيارات أ وب وج وأربعة سيناريوهات", /Option A/i.test(report) && /Option B/i.test(report) && /Option C/i.test(report) && Math.max(n(/scenario/gi), (sectionOf(report, "Part X:").match(/^(\d+\.\s|### )/gm) ?? []).length) >= 4, `${(sectionOf(report, "Part X:").match(/^(\d+\.\s|### )/gm) ?? []).length} scenarios in Part X; Options A, B and C ${/Option A/i.test(report) && /Option B/i.test(report) && /Option C/i.test(report) ? "present" : "missing"}`, "الخيارات والسيناريوهات"),
    c("customer", "Relevance to the customer: decisions for senior consideration", "الصلة بالعميل: قرارات للنظر الأعلى", /decisions? (requiring|for) senior/i.test(report), "A decisions section", "قسم القرارات"),
    c("bluf", "Argumentation: bottom line first and key judgments", "الحجة: الخلاصة أولًا والأحكام الرئيسية", /bottom line/i.test(report) && /key judgments?/i.test(report), "Bottom line and key judgments", "الخلاصة والأحكام"),
    c("change", "Consistency and change: what would change the assessment", "الاتساق والتغير: ما الذي يغيّر التقييم", /would change|what changed|conditions that would/i.test(report), "A change statement", "بيان التغير"),
    c("dissent", "Dissent and red team preserved", "الخلاف والفريق الأحمر محفوظان", /red.team/i.test(report) && /strongest (argument|objection)/i.test(report), "Red-team memorandum", "مذكرة الفريق الأحمر"),
    c("indicators", "Indicators and warnings with thresholds", "المؤشرات والإنذارات بعتبات", (dash?.indicators.length ?? 0) >= 3, `${dash?.indicators.length ?? 0} indicators`, `${dash?.indicators.length ?? 0} مؤشرات`),
    c("accuracy", "Accuracy: no unverified fact reference", "الدقة: لا إحالة حقيقة غير مُتحقق منها", !/unverified reference/.test(report), "Unverified references are marked by the route", "تُعلَّم الإحالات غير المتحقق منها"),
    c("visual", "Visuals: a valid decision dashboard with initiatives", "العناصر المرئية: لوحة قرار صالحة بمبادرات", (dash?.initiatives.length ?? 0) >= 5, `${dash?.initiatives.length ?? 0} initiatives`, `${dash?.initiatives.length ?? 0} مبادرات`),
    c("gaps", "Collection requirements and gaps stated", "متطلبات الجمع والفجوات معلنة", /evidence gaps?|not estimated|collection/i.test(report), "Gaps stated", "الفجوات معلنة"),
  ];
}

// ---- the Strategy Review Engine: has the picture moved since the strategy was written? ----
export type StateAt = { at: string; posture: string | null; value: number | null; ability: number | null; risk: number | null; alerts: string[]; builds: Record<string, string>; lens: Record<string, number | null>; counts?: Record<string, number>; tone?: number | null };
export const stateOf = (c: CaseData, at = new Date().toISOString()): StateAt => ({ at, posture: c.posture.posture, value: c.posture.value, ability: c.posture.ability, risk: c.posture.risk, alerts: (c.deep?.readings ?? []).filter((r) => r.state === "alert").map((r) => r.id), builds: Object.fromEntries((c.deep?.builds ?? []).filter((x) => x.built).map((x) => [x.file, x.built!.slice(0, 10)])), lens: Object.fromEntries(c.lenses.map((l) => [l.id, l.pos])), counts: Object.fromEntries(Object.entries(c.capture?.series ?? {}).map(([k, v]) => [k, v[v.length - 1] ?? 0])), tone: c.tone?.g ?? null });
export type Review = { due: boolean; reasons: { en: string; ar: string }[]; days: number };
export function reviewStrategy(then: StateAt, now: StateAt, dash: Dashboard | null, today: number): Review {
  const r: Review["reasons"] = []; const days = Math.floor((today - Date.parse(then.at)) / 86_400_000);
  if (then.posture !== now.posture) r.push({ en: `The rule-based posture moved from ${then.posture ?? "none"} to ${now.posture ?? "none"}.`, ar: `تغيّر الموقف القائم على القواعد من ${then.posture ?? "لا شيء"} إلى ${now.posture ?? "لا شيء"}.` });
  for (const [k, en, ar] of [["value", "Value to the UAE", "القيمة للإمارات"], ["ability", "UAE ability to act", "قدرة الإمارات على الفعل"], ["risk", "Risk", "المخاطر"]] as const) { const a = then[k]; const b = now[k]; if (a != null && b != null && Math.abs(a - b) >= 10) r.push({ en: `${en} moved ${a} to ${b} (10 points or more).`, ar: `${ar} من ${a} إلى ${b} (10 نقاط فأكثر).` }); }
  const na = now.alerts.filter((x) => !then.alerts.includes(x)); if (na.length) r.push({ en: `New indicators in alert: ${na.join(", ")}.`, ar: `مؤشرات جديدة في حالة إنذار: ${na.join("، ")}.` });
  const ch = Object.keys(now.builds).filter((f) => then.builds[f] !== now.builds[f]); if (ch.length) r.push({ en: `Data builds changed: ${ch.join(", ")}.`, ar: `تغيرت إصدارات البيانات: ${ch.join("، ")}.` });
  if (days >= 90) r.push({ en: `${days} days since the strategy was written: the 90-day review is due.`, ar: `مرّ ${days} يومًا على كتابة الاستراتيجية: المراجعة بعد 90 يومًا مستحقة.` });
  const past = (dash?.initiatives ?? []).filter((i) => i.gateDate && Date.parse(`${i.gateDate}-28`) <= today); if (past.length) r.push({ en: `Decision gates reached: ${past.map((i) => `${i.id} (${i.gateDate})`).join(", ")}.`, ar: `بلغت نقاط القرار: ${past.map((i) => `${i.id} (${i.gateDate})`).join("، ")}.` });
  return { due: r.length > 0, reasons: r, days };
}
